/**
 * Pro Plan Code Deployment & ZIP Bundle Engine
 *
 * For Pro / Enterprise users:
 * When code is generated by Flash AI, this engine:
 * 1. Automatically bundles the complete source code into a ready-to-open .zip file with package.json, index.html, and README.
 * 2. Generates an instant, live previewable web sub-link:
 *    https://app-7r35kmgp19mp.appmedo.com/app/{slug}
 * 3. Provides a customizable slug editor (e.g. /my-app, /crypto-dashboard).
 * 4. Stores deployed apps in localStorage so they persist and can be opened in the standalone preview route!
 */

import JSZip from 'jszip';

export interface DeployedApp {
  id: string;
  slug: string;
  title: string;
  description: string;
  subLinkUrl: string;
  createdAt: number;
  updatedAt: number;
  files: Record<string, string>;
  language: string;
  entryHtml: string;
}

const STORAGE_KEY = 'flash_pro_deployed_apps';

class ProDeploymentService {
  private deployedApps: DeployedApp[] = [];

  constructor() {
    if (typeof window !== 'undefined') {
      const saved = localStorage.getItem(STORAGE_KEY);
      if (saved) {
        try {
          this.deployedApps = JSON.parse(saved);
        } catch {
          this.deployedApps = [];
        }
      }
    }
  }

  public getDeployedApps(): DeployedApp[] {
    return [...this.deployedApps];
  }

  public getAppBySlug(slug: string): DeployedApp | undefined {
    return this.deployedApps.find((a) => a.slug.toLowerCase() === slug.toLowerCase());
  }

  /**
   * Automatically packages code and creates a Pro sub-link deployment
   */
  public deployCodeSnippet(
    title: string,
    code: string,
    language: string,
    customSlug?: string
  ): DeployedApp {
    const rawSlug = customSlug || title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '') || 'my-app';
    let uniqueSlug = rawSlug;
    let counter = 1;

    // Ensure uniqueness
    while (this.deployedApps.some((a) => a.slug.toLowerCase() === uniqueSlug.toLowerCase())) {
      uniqueSlug = `${rawSlug}-${counter++}`;
    }

    const host = typeof window !== 'undefined' ? window.location.host : 'app-7r35kmgp19mp.appmedo.com';
    const subLinkUrl = `https://${host}/app/${uniqueSlug}`;

    // Structure project files
    const files: Record<string, string> = {
      'README.md': `# ${title}\n\nGenerated with Flash AI Pro Deployment Engine.\n\nLive Link: ${subLinkUrl}\n\n## Quick Start\n\`\`\`bash\nnpm install\nnpm run dev\n\`\`\`\n`,
      'package.json': JSON.stringify(
        {
          name: uniqueSlug,
          version: '1.0.0',
          private: true,
          scripts: {
            dev: 'vite',
            build: 'vite build',
          },
          dependencies: {
            lucide: '^0.468.0',
            tailwindcss: '^3.4.1',
          },
        },
        null,
        2
      ),
    };

    let entryHtml = '';
    const cleanLang = language.toLowerCase();

    if (cleanLang === 'html' || code.includes('<!DOCTYPE') || code.includes('<html')) {
      files['index.html'] = code;
      entryHtml = code;
    } else if (cleanLang === 'css') {
      files['style.css'] = code;
      files['index.html'] = `<!DOCTYPE html>\n<html><head><style>${code}</style></head><body><div id="app"><h1>${title}</h1></div></body></html>`;
      entryHtml = files['index.html'];
    } else if (cleanLang === 'javascript' || cleanLang === 'js' || cleanLang === 'ts' || cleanLang === 'tsx') {
      files['src/main.js'] = code;
      files['index.html'] = `<!DOCTYPE html>\n<html><head><title>${title}</title><meta charset="utf-8" /></head><body style="margin:0;background:#0F172A;color:#fff;font-family:sans-serif;padding:2rem;"><div id="root"></div><script type="module">${code}</script></body></html>`;
      entryHtml = files['index.html'];
    } else {
      files[`src/app.${language || 'txt'}`] = code;
      files['index.html'] = `<!DOCTYPE html>\n<html><head><title>${title}</title><meta charset="utf-8" /></head><body style="margin:0;background:#0F172A;color:#fff;font-family:monospace;padding:2rem;"><pre>${code.replace(/</g, '&lt;')}</pre></body></html>`;
      entryHtml = files['index.html'];
    }

    const newApp: DeployedApp = {
      id: `app_${Date.now()}`,
      slug: uniqueSlug,
      title: title || 'Custom Web App',
      description: `Instant Pro deployment with live sub-link: /app/${uniqueSlug}`,
      subLinkUrl,
      createdAt: Date.now(),
      updatedAt: Date.now(),
      files,
      language,
      entryHtml,
    };

    this.deployedApps.unshift(newApp);
    this.save();
    return newApp;
  }

  public updateSlug(appId: string, newSlug: string): boolean {
    const cleanSlug = newSlug.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
    if (!cleanSlug) return false;

    // Check collision with another app
    if (this.deployedApps.some((a) => a.id !== appId && a.slug.toLowerCase() === cleanSlug)) {
      return false;
    }

    const host = typeof window !== 'undefined' ? window.location.host : 'app-7r35kmgp19mp.appmedo.com';
    this.deployedApps = this.deployedApps.map((a) => {
      if (a.id === appId) {
        return {
          ...a,
          slug: cleanSlug,
          subLinkUrl: `https://${host}/app/${cleanSlug}`,
          updatedAt: Date.now(),
        };
      }
      return a;
    });

    this.save();
    return true;
  }

  /**
   * Generates and downloads the complete project as a ready-to-open ZIP
   */
  public async downloadAppZip(app: DeployedApp): Promise<void> {
    const zip = new JSZip();
    for (const [path, content] of Object.entries(app.files)) {
      zip.file(path, content);
    }
    const blob = await zip.generateAsync({ type: 'blob' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `${app.slug}-pro-bundle.zip`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  }

  private save(): void {
    if (typeof window !== 'undefined') {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(this.deployedApps));
    }
  }
}

export const proDeploymentService = new ProDeploymentService();
